package com.peopleai.jobs.model;
import jakarta.persistence.*;import jakarta.validation.constraints.NotBlank;
@Entity @Table(name="jobs") public class Job {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@NotBlank private String title;@NotBlank private String location;private String salary;@NotBlank private String status="Open";@Column(length=2000)private String description;protected Job(){}public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String x){title=x;}public String getLocation(){return location;}public void setLocation(String x){location=x;}public String getSalary(){return salary;}public void setSalary(String x){salary=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}public String getDescription(){return description;}public void setDescription(String x){description=x;}}
